using System;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview
{
    [Serializable] public class PythonAutoPlayOption {public string choice,label,status;public bool can_start;}
    [Serializable] public class PythonAutoPlayDecision {public int day;public string target,choice,reason,subject,status;}
    [Serializable] public class PythonAutoPlayReport {public int version,limit,days,operations;public string run_id,objective,mode,reason,message,summary;public bool running;public string[] lines;public PythonAutoPlayDecision[] decisions;}
    [Serializable] public class PythonAutoPlay {public bool running,can_start,paused;public string reason,notes;public PythonAutoPlayOption[] objectives,modes;public PythonAutoPlayReport report;}
    public class PythonAutoPlayPanel : MonoBehaviour
    {
        public GameObject panel,confirmation,activity;public Button activityStop,activityDetails;public Text activityStatus;public Dropdown objectives,modes,days;public Text title,details,notice,confirmationText;public Button proceed,stop,save,close,confirm,cancel,previous,next;public Button[] tabs;
        private PythonCafeState current;private string instance,identity,runId,objective,mode="basic",message="";private int selectedDays=10,tab,page;private bool online,choosing,wasRunning;
        private PythonStateClient Client=>GetComponent<PythonStateClient>();private PythonAutoPlay View=>current?.autoplay;private PythonAutoPlayReport Report=>View?.report;
        private PythonAutoPlayOption Target=>Array.Find(View?.objectives ?? new PythonAutoPlayOption[0],r=>r.choice==objective);
        public void Open(){if(!online || View==null || (!Client.CanManageSaves && !Client.AutoPlayRunning))return;Client.PauseAutomaticForSave();panel.SetActive(true);Focus();Render();ResetScroll();}
        public void Close(){Clear();panel.SetActive(false);}
        public void ResetSelection(){Clear();wasRunning=false;objective=null;mode="basic";selectedDays=10;tab=page=0;message="";runId=null;panel.SetActive(false);}
        private void Clear(){choosing=false;confirmation.SetActive(false);}
        public void SelectObjective(int i){if(!online || !Client.CanManageSaves || i<0 || i>=(View?.objectives?.Length ?? 0))return;objective=View.objectives[i].choice;Clear();Render();ResetScroll();}
        public void SelectMode(int i){if(!online || !Client.CanManageSaves || i<0 || i>=(View?.modes?.Length ?? 0))return;mode=View.modes[i].choice;Clear();Render();ResetScroll();}
        public void SelectDays(int i){if(!online || !Client.CanManageSaves || i<0 || i>=10)return;selectedDays=i+1;Clear();Render();}
        public void Result(){SelectTab(0);}public void Decisions(){SelectTab(1);}public void Log(){SelectTab(2);}private void SelectTab(int value){tab=value;page=0;Render();ResetScroll();}
        public void Previous(){if(page>0){page--;Render();ResetScroll();}}public void Next(){if(page+1<PageCount){page++;Render();ResetScroll();}}
        public void Choose(){if(!online)return;if(View?.running==true){Client.ResumeAutoPlay();GetComponent<PythonMenuPanel>()?.ClearReturnContext();Close();return;}if(!online || !Client.CanStartAutoPlay(objective,mode,selectedDays))return;choosing=true;confirmation.SetActive(true);confirmation.transform.SetAsLastSibling();confirmationText.text=(Target?.label ?? objective)+"目標 / "+(Array.Find(View.modes,r=>r.choice==mode)?.label ?? mode)+" / 最大"+selectedDays+"日のおまかせを開始しますか？\n\n"+View.notes+"\n\n現在の資金："+current.funds.ToString("0.#")+" / "+current.day+"日目";Canvas.ForceUpdateCanvases();confirmationText.GetComponentInParent<ScrollRect>(true).verticalNormalizedPosition=1;RefreshControls();}
        public void Confirm(){if(!online || !choosing || !Client.CanStartAutoPlay(objective,mode,selectedDays))return;Clear();Client.StartAutoPlay(objective,mode,selectedDays);GetComponent<PythonMenuPanel>()?.ClearReturnContext();Close();}
        public void Cancel(){Clear();RefreshControls();}public void Stop(){Client.StopAutoPlay();}public void Save(){if(online && Report!=null && !View.running)Client.SaveGame();}
        public void Apply(PythonCafeState state){if(instance!=state.instance_id){instance=state.instance_id;ResetSelection();}current=state;online=true;if(wasRunning && View?.running!=true)message="";wasRunning=View?.running==true;string key=state.instance_id+"/"+state.revision;if(identity!=key){identity=key;Clear();}if(runId!=Report?.run_id){runId=Report?.run_id;message="";tab=page=0;}Render();Focus();}
        static void Fill(Dropdown d,string[] labels,int value){d.options.Clear();foreach(var label in labels)d.options.Add(new Dropdown.OptionData(label));if(labels.Length==0)d.options.Add(new Dropdown.OptionData("対象目標なし"));d.SetValueWithoutNotify(Math.Max(0,value));d.RefreshShownValue();}
        private int PageCount=>tab==1 ? Math.Max(1,((Report?.decisions?.Length ?? 0)+5)/6) : tab==2 ? Math.Max(1,((Report?.lines?.Length ?? 0)+9)/10) : 1;
        private static string Reason(string reason){switch(reason){case "day_limit":return "指定日数に到達";case "goal_cleared":return "目標の段階を達成";case "completed":return "目標達成";case "expired":return "人気目標の期限切れ";case "game_over":return "ゲームオーバー";case "cancelled":return "中断";case "blocked":return "回答待ち・進行できません";case "operation_limit":return "操作上限に到達";default:return "待機中";}}
        private void Render(){var targets=View?.objectives ?? new PythonAutoPlayOption[0];if(!Array.Exists(targets,r=>r.choice==objective))objective=(targets.FirstOrDefault(r=>r.choice==current?.objective && r.can_start) ?? targets.FirstOrDefault(r=>r.can_start) ?? targets.FirstOrDefault())?.choice;Fill(objectives,targets.Select(r=>r.label+(r.can_start ? "（挑戦中）" : "（条件を確認）")).ToArray(),Array.FindIndex(targets,r=>r.choice==objective));var policies=View?.modes ?? new PythonAutoPlayOption[0];Fill(modes,policies.Select(r=>r.label).ToArray(),Array.FindIndex(policies,r=>r.choice==mode));Fill(days,Enumerable.Range(1,10).Select(i=>i+"日").ToArray(),selectedDays-1);page=Math.Min(page,PageCount-1);title.text="おまかせ / 方針・複数日進行";
            if(tab==0)details.text=Report==null ? (View?.notes ?? "情報がありません。")+"\n\n"+(View?.reason ?? "")+"\n目標："+(Target?.label ?? "対象なし")+(Target?.can_start==false ? " / 挑戦中の目標が必要です。" : "") : (View.running ? "実行中" : Reason(Report.reason))+" / "+Report.days+" / "+Report.limit+"日 / "+Report.operations+"操作\n実行設定："+(Report.objective=="bond" ? "好感度" : Report.objective=="patron" ? "有力者" : "人気")+" / "+(Report.mode=="clear" ? "安定経営" : Report.mode=="fast" ? "積極経営" : "基礎営業")+"\n"+Report.message+"\n\n"+Report.summary+"\n\n終了後は保存ボタンで現在の状態と実行記録を保存できます。";
            else if(tab==1)details.text="判断一覧 / "+(page+1)+" / "+PageCount+"ページ\n\n"+string.Join("\n\n",(Report?.decisions ?? new PythonAutoPlayDecision[0]).Skip(page*6).Take(6).Select(r=>r.day+"日目 / "+r.target+"："+r.choice+" / "+r.status+"\n"+r.reason));
            else details.text="操作ログ / "+(page+1)+" / "+PageCount+"ページ\n\n"+string.Join("\n",(Report?.lines ?? new string[0]).Skip(page*10).Take(10));RefreshControls();}
        private void ResetScroll(){Canvas.ForceUpdateCanvases();details.GetComponentInParent<ScrollRect>(true).verticalNormalizedPosition=1;}
        public void RefreshControls(){RefreshActivity();bool ready=online && Client.CanManageSaves && !choosing;objectives.interactable=ready && (View?.objectives?.Length ?? 0)>0;modes.interactable=days.interactable=ready;proceed.GetComponentInChildren<Text>().text=View?.running==true ? "実行を続ける" : "おまかせ開始（確認へ）";proceed.interactable=online && !choosing && (View?.running==true ? Client.CanSendCommands && !Client.BatchAutomatic && !Client.BatchStopping : Client.CanStartAutoPlay(objective,mode,selectedDays));stop.interactable=online && !Client.BatchStopping && (Client.AutoPlayRunning || Client.BatchAutomatic);save.interactable=ready && Report!=null;confirm.interactable=online && choosing && Client.CanStartAutoPlay(objective,mode,selectedDays);cancel.interactable=close.interactable=true;close.GetComponentInChildren<Text>().text=View?.running==true || Client.BatchAutomatic ? "営業画面へ（実行を継続）" : "営業画面へ";previous.interactable=page>0;next.interactable=page+1<PageCount;for(int i=0;i<tabs.Length;i++)tabs[i].GetComponent<Image>().color=tab==i ? new Color(.78f,.88f,.74f) : Color.white;notice.text=!online ? "未接続です。自動実行を止めています。再接続後に続けるか中止を選べます。" : Client.BatchStopping ? "中止を要求しています。送信中の操作が終わってから停止します。" : View?.running==true ? (Client.BatchAutomatic ? "おまかせ実行中" : "実行は待機中です。続けるか中止を選んでください。")+" / "+(Report?.days ?? 0)+" / "+(Report?.limit ?? selectedDays)+"日" : !Client.CanManageSaves ? "操作を送信しています。" : message!="" ? message : Report==null ? View?.reason ?? "" : "実行結果を確認し、必要なら保存してください。";}
        private void RefreshActivity(){if(activity==null)return;bool active=Client.AutoPlayRunning || Client.BatchAutomatic || Client.BatchStopping;activity.SetActive(active || Report!=null);var service=GetComponent<PythonServiceScreen>();if(service!=null && service.heading!=null)service.heading.gameObject.SetActive(!activity.activeSelf);activityStop.interactable=online && active && !Client.BatchStopping;activityDetails.interactable=online && View!=null;activityStatus.text=!active && Report!=null ? "おまかせ終了 / "+Reason(Report.reason) : Client.BatchStopping ? "おまかせ：停止しています…" : !online ? "おまかせ：接続待ち・一時停止" : !Client.BatchAutomatic ? "おまかせ：一時停止中" : "おまかせ / "+(current?.day ?? 1)+"日目 / 完了 "+(Report?.days ?? 0)+" / "+(Report?.limit ?? selectedDays)+"日";}
        public void Focus(){if(panel.activeSelf)panel.transform.SetAsLastSibling();}
        public void Notify(string text){message=text;RefreshControls();}public void Disconnect(){online=false;Clear();RefreshControls();}
    }
}
